./ci/utils.sh:1:#!/bin/bash
./ci/utils.sh:2:
./ci/utils.sh:3:# Various utility functions used through CI.
./ci/utils.sh:4:
./ci/utils.sh:5:# Finds Cargo's `OUT_DIR` directory from the most recent build.
./ci/utils.sh:6:#
./ci/utils.sh:7:# This requires one parameter corresponding to the target directory
./ci/utils.sh:8:# to search for the build output.
./ci/utils.sh:9:cargo_out_dir() {
./ci/utils.sh:10:    # This works by finding the most recent stamp file, which is produced by
./ci/utils.sh:11:    # every ripgrep build.
./ci/utils.sh:12:    target_dir="$1"
./ci/utils.sh:13:    find "$target_dir" -name ripgrep-stamp -print0 \
./ci/utils.sh:14:      | xargs -0 ls -t \
./ci/utils.sh:15:      | head -n1 \
./ci/utils.sh:16:      | xargs dirname
./ci/utils.sh:17:}
./ci/utils.sh:18:
./ci/utils.sh:19:host() {
./ci/utils.sh:20:    case "$TRAVIS_OS_NAME" in
./ci/utils.sh:21:        linux)
./ci/utils.sh:22:            echo x86_64-unknown-linux-gnu
./ci/utils.sh:23:            ;;
./ci/utils.sh:24:        osx)
./ci/utils.sh:25:            echo x86_64-apple-darwin
./ci/utils.sh:26:            ;;
./ci/utils.sh:27:    esac
./ci/utils.sh:28:}
./ci/utils.sh:29:
./ci/utils.sh:30:architecture() {
./ci/utils.sh:31:    case "$TARGET" in
./ci/utils.sh:32:        x86_64-*)
./ci/utils.sh:33:            echo amd64
./ci/utils.sh:34:            ;;
./ci/utils.sh:35:        i686-*|i586-*|i386-*)
./ci/utils.sh:36:            echo i386
./ci/utils.sh:37:            ;;
./ci/utils.sh:38:        arm*-unknown-linux-gnueabihf)
./ci/utils.sh:39:            echo armhf
./ci/utils.sh:40:            ;;
./ci/utils.sh:41:        *)
./ci/utils.sh:42:            die "architecture: unexpected target $TARGET"
./ci/utils.sh:43:            ;;
./ci/utils.sh:44:    esac
./ci/utils.sh:45:}
./ci/utils.sh:46:
./ci/utils.sh:47:gcc_prefix() {
./ci/utils.sh:48:    case "$(architecture)" in
./ci/utils.sh:49:        armhf)
./ci/utils.sh:50:            echo arm-linux-gnueabihf-
./ci/utils.sh:51:            ;;
./ci/utils.sh:52:        *)
./ci/utils.sh:53:            return
./ci/utils.sh:54:            ;;
./ci/utils.sh:55:    esac
./ci/utils.sh:56:}
./ci/utils.sh:57:
./ci/utils.sh:58:is_musl() {
./ci/utils.sh:59:    case "$TARGET" in
./ci/utils.sh:60:        *-musl) return 0 ;;
./ci/utils.sh:61:        *)      return 1 ;;
./ci/utils.sh:62:    esac
./ci/utils.sh:63:}
./ci/utils.sh:64:
./ci/utils.sh:65:is_x86() {
./ci/utils.sh:66:    case "$(architecture)" in
./ci/utils.sh:67:      amd64|i386) return 0 ;;
./ci/utils.sh:68:      *)          return 1 ;;
./ci/utils.sh:69:    esac
./ci/utils.sh:70:}
./ci/utils.sh:71:
./ci/utils.sh:72:is_x86_64() {
./ci/utils.sh:73:    case "$(architecture)" in
./ci/utils.sh:74:      amd64) return 0 ;;
./ci/utils.sh:75:      *)          return 1 ;;
./ci/utils.sh:76:    esac
./ci/utils.sh:77:}
./ci/utils.sh:78:
./ci/utils.sh:79:is_arm() {
./ci/utils.sh:80:    case "$(architecture)" in
./ci/utils.sh:81:        armhf) return 0 ;;
./ci/utils.sh:82:        *)     return 1 ;;
./ci/utils.sh:83:    esac
./ci/utils.sh:84:}
./ci/utils.sh:85:
./ci/utils.sh:86:is_linux() {
./ci/utils.sh:87:    case "$TRAVIS_OS_NAME" in
./ci/utils.sh:88:        linux) return 0 ;;
./ci/utils.sh:89:        *)     return 1 ;;
./ci/utils.sh:90:    esac
./ci/utils.sh:91:}
./ci/utils.sh:92:
./ci/utils.sh:93:is_osx() {
./ci/utils.sh:94:    case "$TRAVIS_OS_NAME" in
./ci/utils.sh:95:        osx) return 0 ;;
./ci/utils.sh:96:        *)   return 1 ;;
./ci/utils.sh:97:    esac
./ci/utils.sh:98:}
./ci/utils.sh:99:
./ci/utils.sh:100:builder() {
./ci/utils.sh:101:    if is_musl && is_x86_64; then
./ci/utils.sh:102:        cargo install cross
./ci/utils.sh:103:        echo "cross"
./ci/utils.sh:104:    else
./ci/utils.sh:105:        echo "cargo"
./ci/utils.sh:106:    fi
./ci/utils.sh:107:}
