./build.rs:13:    static MANIFEST: &str = "pkg/windows/Manifest.xml";
./build.rs:14:
./build.rs:15:    let Ok(target_os) = std::env::var("CARGO_CFG_TARGET_OS") else { return };
./build.rs:16:    let Ok(target_env) = std::env::var("CARGO_CFG_TARGET_ENV") else { return };
./build.rs:17:    if !(target_os == "windows" && target_env == "msvc") {
./build.rs:18:        return;
./build.rs:19:    }
./build.rs:20:
./build.rs:21:    let Ok(mut manifest) = std::env::current_dir() else { return };
./build.rs:22:    manifest.push(MANIFEST);
./build.rs:23:    let Some(manifest) = manifest.to_str() else { return };
./build.rs:24:
./build.rs:25:    println!("cargo:rerun-if-changed={MANIFEST}");
./build.rs:26:    // Embed the Windows application manifest file.
./build.rs:27:    println!("cargo:rustc-link-arg-bin=rg=/MANIFEST:EMBED");
./build.rs:28:    println!("cargo:rustc-link-arg-bin=rg=/MANIFESTINPUT:{manifest}");
./build.rs:29:    // Turn linker warnings into errors. Helps debugging, otherwise the
./build.rs:30:    // warnings get squashed (I believe).
