./tests/util.rs:497:    if cfg!(target_arch = "powerpc64") {
./tests/util.rs:498:        Some("qemu-ppc64".to_string())
./tests/util.rs:499:    } else if cfg!(target_arch = "x86") {
./tests/util.rs:500:        Some("i386".to_string())
