/// Parses a possible reference to a capture group name in the given text,
/// starting at the beginning of `replacement`.
///
/// If no such valid reference could be found, None is returned.
#[inline]
fn find_cap_ref(replacement: &[u8]) -> Option<CaptureRef<'_>> {
    let mut i = 0;
    if replacement.len() <= 1 || replacement[0] != b'$' {
        return None;
    }
    let mut brace = false;
    i += 1;
    if replacement[i] == b'{' {
        brace = true;
        i += 1;
    }
    let mut cap_end = i;
    while replacement.get(cap_end).map_or(false, is_valid_cap_letter) {
        cap_end += 1;
    }
    if cap_end == i {
        return None;
    }
    // We just verified that the range 0..cap_end is valid ASCII, so it must
    // therefore be valid UTF-8. If we really cared, we could avoid this UTF-8
    // check with an unchecked conversion or by parsing the number straight
    // from &[u8].
    let cap = std::str::from_utf8(&replacement[i..cap_end])
        .expect("valid UTF-8 capture name");
    if brace {
        if !replacement.get(cap_end).map_or(false, |&b| b == b'}') {
            return None;
        }
        cap_end += 1;
    }
    Some(CaptureRef {
        cap: match cap.parse::<u32>() {
            Ok(i) => Ref::Number(i as usize),
            Err(_) => Ref::Named(cap),
        },
        end: cap_end,
    })
}

/// Returns true if and only if the given byte is allowed in a capture name.
#[inline]
fn is_valid_cap_letter(b: &u8) -> bool {
    match *b {
        b'0'..=b'9' | b'a'..=b'z' | b'A'..=b'Z' | b'_' => true,
        _ => false,
    }
}

/** Looks up a single action handler by its dot-separated path. */
export async function getAction(
	manifest: SSRManifest,
	path: string,
): Promise<ActionClient<unknown, ActionAccept, $ZodType>> {
	const pathKeys = path.split('.').map((key) => decodeURIComponent(key));
	let { server } = await getActions(manifest);

	if (!server || !(typeof server === 'object')) {
		throw new TypeError(
			`Expected \`server\` export in actions file to be an object. Received ${typeof server}.`,
		);
	}

	for (const key of pathKeys) {
		// An action is a leaf: once resolved to a function, its own properties
		// are not part of the action namespace and cannot be traversed further.
		if (typeof server === 'function') {
			throw new AstroError({
				...ActionNotFoundError,
				message: ActionNotFoundError.message(pathKeys.join('.')),
			});
		}
		if (FORBIDDEN_PATH_KEYS.has(key)) {
			throw new AstroError({
				...ActionNotFoundError,
				message: ActionNotFoundError.message(pathKeys.join('.')),
			});
		}
		if (!Object.hasOwn(server, key)) {
			throw new AstroError({
				...ActionNotFoundError,
				message: ActionNotFoundError.message(pathKeys.join('.')),
			});
		}
		// @ts-expect-error we are doing a recursion... it's ugly
		server = server[key];
	}
	if (typeof server !== 'function') {
		throw new TypeError(
			`Expected handler for action ${pathKeys.join('.')} to be a function. Received ${typeof server}.`,
		);
	}
	return server;
}

/**
 * Keys that must be rejected when traversing object paths (e.g. dot-separated
 * property lookups) to prevent prototype-pollution attacks.
 */
export const FORBIDDEN_PATH_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

/**
 * Pure decision function for the route guard middleware.
 *
 * Determines whether a request should be blocked (file exists at project root
 * but outside srcDir/publicDir) or allowed through. The filesystem lookups are
 * injected via `fsInfo` so this function remains pure and unit-testable.
 */
export function evaluateRouteGuard(
	url: string,
	acceptHeader: string,
	fsInfo: RouteGuardFsInfo,
): RouteGuardDecision {
	// Only intercept requests that look like browser navigation (HTML requests)
	if (!acceptHeader.includes('text/html')) {
		return { action: 'next' };
	}

	let pathname: string;
	try {
		pathname = decodeURI(new URL(url, 'http://localhost').pathname);
	} catch {
		// Malformed URI, let other middleware handle it
		return { action: 'next' };
	}

	// Always allow Vite internal paths through
	if (VITE_INTERNAL_PREFIXES.some((prefix) => pathname.startsWith(prefix))) {
		return { action: 'next' };
	}

	// Always allow requests with query params (Vite transform requests like ?url, ?raw)
	if (url.includes('?')) {
		return { action: 'next' };
	}

	// Allow if file exists in publicDir or srcDir
	if (fsInfo.existsInPublic || fsInfo.existsInSrc) {
		return { action: 'next' };
	}

	// Block files that exist at project root but not in srcDir or publicDir
	// Directories are allowed — they may share names with valid page routes
	if (fsInfo.existsAtRootAsFile) {
		return { action: 'block', pathname };
	}

	// File doesn't exist anywhere, let other middleware handle it
	return { action: 'next' };
}

