 2	import type { $ZodType } from 'zod/v4/core';
 3	import { ActionNotFoundError } from '../core/errors/errors-data.js';
 4	import { AstroError } from '../core/errors/index.js';
 5	import { createAsyncManifestMemo } from '../core/manifest/memo.js';
 6	import type { SSRActions, SSRManifest } from '../types/public/internal.js';
 7	import { NOOP_ACTIONS_MOD } from './noop-actions.js';
 8	import type { ActionAccept, ActionClient } from './runtime/types.js';
 9	
10	const actionsMemo = createAsyncManifestMemo(async (manifest) =>
11		manifest.actions ? await manifest.actions() : NOOP_ACTIONS_MOD,
12	);
13	
14	/** Resolves the actions module from the manifest (a no-op module when none). */
15	export function getActions(manifest: SSRManifest): Promise<SSRActions> {
16		return actionsMemo.get(manifest);
17	}
18	
19	/**
20	 * Clears the cached actions so they are re-resolved on the next request.
21	 * Called via HMR when action files change during development.
22	 */
23	export function clearActions(manifest: SSRManifest): void {
24		actionsMemo.invalidate(manifest);
25	}
26	
27	/** Looks up a single action handler by its dot-separated path. */
28	export async function getAction(
29		manifest: SSRManifest,
30		path: string,
31	): Promise<ActionClient<unknown, ActionAccept, $ZodType>> {
32		const pathKeys = path.split('.').map((key) => decodeURIComponent(key));
33		let { server } = await getActions(manifest);
34	
35		if (!server || !(typeof server === 'object')) {
36			throw new TypeError(
37				`Expected \`server\` export in actions file to be an object. Received ${typeof server}.`,
38			);
39		}
40	
41		for (const key of pathKeys) {
42			// An action is a leaf: once resolved to a function, its own properties
43			// are not part of the action namespace and cannot be traversed further.
44			if (typeof server === 'function') {
45				throw new AstroError({
46					...ActionNotFoundError,
47					message: ActionNotFoundError.message(pathKeys.join('.')),
48				});
49			}
50			if (FORBIDDEN_PATH_KEYS.has(key)) {
51				throw new AstroError({
52					...ActionNotFoundError,
53					message: ActionNotFoundError.message(pathKeys.join('.')),
54				});
55			}
56			if (!Object.hasOwn(server, key)) {
57				throw new AstroError({
58					...ActionNotFoundError,
59					message: ActionNotFoundError.message(pathKeys.join('.')),
60				});
61			}
62			// @ts-expect-error we are doing a recursion... it's ugly
63			server = server[key];
64		}
65		if (typeof server !== 'function') {
66			throw new TypeError(
67				`Expected handler for action ${pathKeys.join('.')} to be a function. Received ${typeof server}.`,
68			);
69		}
